package org.sleepwell.app;
import android.content.Context;import android.graphics.*;import android.view.*;
/** Original moon/orb and rounded hurdle art; no copied game assets. */
final class JumpView extends View {
 final JumpGame game;final Paint paint=new Paint(3);boolean down;
 JumpView(Context c,JumpGame game,Runnable jump){super(c);this.game=game;setContentDescription("Jump game · tap to jump");setFocusable(true);setClickable(true);setOnClickListener(v->jump.run());}
 @Override protected void onMeasure(int w,int h){int width=MeasureSpec.getSize(w);setMeasuredDimension(width,resolveSize(Math.max(Design.dp(getContext(),190),Math.round(width*.42f)),h));}
 @Override protected void onDraw(Canvas c){super.onDraw(c);c.save();float scale=Math.min(getWidth()/1000f,getHeight()/420f);c.translate((getWidth()-1000*scale)/2,(getHeight()-420*scale)/2);c.scale(scale,scale);paint.setShader(new LinearGradient(0,0,0,420,new int[]{0xff2c233c,0xff47345c},null,Shader.TileMode.CLAMP));c.drawRoundRect(0,0,1000,420,34,34,paint);paint.setShader(null);paint.setColor(0xffccb6f3);for(int n=0;n<14;n++){float x=45+n*71,y=30+n*43%115;c.drawCircle(x,y,n%3==0?3:2,paint);}paint.setColor(0xff705780);c.drawRoundRect(30,330,970,335,2,2,paint);if(!game.complete()){paint.setColor(0xfff4bc72);c.drawRoundRect((float)game.obstacleX,(float)(JumpGame.FLOOR-game.obstacleHeight()),(float)(game.obstacleX+game.obstacleWidth()),330,8,8,paint);paint.setColor(0xfffbdca5);c.drawRoundRect((float)game.obstacleX+7,(float)(JumpGame.FLOOR-game.obstacleHeight()+7),(float)(game.obstacleX+game.obstacleWidth()-7),(float)(JumpGame.FLOOR-game.obstacleHeight()+12),2,2,paint);}float y=(float)(JumpGame.FLOOR-JumpGame.RADIUS-game.height);paint.setColor(0xffd8c5ff);c.drawCircle(180,y,22,paint);paint.setColor(0xff8564ad);c.drawCircle(188,y-7,6,paint);paint.setColor(0xfff0e6ff);c.drawCircle(173,y-9,4,paint);paint.setTypeface(Design.font(getContext(),600));paint.setTextSize(28);paint.setColor(0xffeadffb);c.drawText(game.cleared+" / "+JumpGame.TARGET+" hurdles",36,390,paint);c.restore();}
 @Override public boolean onTouchEvent(android.view.MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){down=true;return true;}if(e.getActionMasked()==MotionEvent.ACTION_CANCEL){down=false;return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP){boolean tap=down;down=false;if(tap&&e.getX()>=0&&e.getX()<=getWidth()&&e.getY()>=0&&e.getY()<=getHeight())performClick();return true;}return true;}
 @Override public boolean performClick(){return super.performClick();}
}
